from dedupe import dedupe


def test_keeps_first_seen_order():
    assert dedupe([3, 1, 3, 2, 1]) == [3, 1, 2]


def test_empty_and_single():
    assert dedupe([]) == []
    assert dedupe(["only"]) == ["only"]


def test_already_unique_is_unchanged():
    assert dedupe(["a", "b", "c"]) == ["a", "b", "c"]


def test_returns_a_list():
    assert isinstance(dedupe(iter("aba")), list)

from dedupe import dedupe, dedupe_by


def counting_gen(values, counter):
    for v in values:
        counter.append(v)
        yield v


def test_generator_is_consumed_once():
    seen = []
    result = dedupe(counting_gen([1, 2, 2, 3], seen))
    assert result == [1, 2, 3]
    assert seen == [1, 2, 2, 3], "the input was iterated more than once"


def test_dedupe_by_accepts_a_generator():
    rows = ({"id": i % 2, "n": i} for i in range(4))
    assert dedupe_by(rows, key=lambda r: r["id"]) == [{"id": 0, "n": 0}, {"id": 1, "n": 1}]

import pytest

from dedupe import dedupe


class Unorderable:
    """Hashable by identity, and raises if compared with <."""

    def __lt__(self, other):
        raise AssertionError("the solution sorted its input")

    __gt__ = __le__ = __ge__ = __lt__


def test_no_sorting():
    a, b = Unorderable(), Unorderable()
    assert dedupe([a, b, a]) == [a, b]


def test_mixed_hashable_types():
    items = [1, "1", (1,), 1, "1"]
    assert dedupe(items) == [1, "1", (1,)]

